import AppKit
import ApplicationServices
import Carbon.HIToolbox

/// Pasteboard types that password managers and other apps use to say "don't keep this".
private let privateTypes: Set<String> = [
    "org.nspasteboard.ConcealedType", "org.nspasteboard.TransientType",
    "org.nspasteboard.AutoGeneratedType", "com.agilebits.onepassword",
    "de.petermaurer.TransientPasteboardType", "com.typeit4me.clipping",
    "Pasteboard generator type", "com.apple.is-remote-clipboard.private",
]

@MainActor
final class Watcher {
    let store: Store
    var onCapture: (Clip) -> Void = { _ in }
    private var lastChange = NSPasteboard.general.changeCount
    private var timer: Timer?

    init(store: Store) { self.store = store }

    func start() {
        let t = Timer(timeInterval: 0.35, repeats: true) { [weak self] _ in
            MainActor.assumeIsolated { self?.tick() }
        }
        RunLoop.main.add(t, forMode: .common)
        timer = t
    }

    /// Called after Clothesline writes to the pasteboard so its own copies aren't captured.
    func skipCurrent() { lastChange = NSPasteboard.general.changeCount }

    private func tick() {
        let pb = NSPasteboard.general
        guard pb.changeCount != lastChange else { return }
        lastChange = pb.changeCount
        let prefs = Prefs.shared
        guard !prefs.paused else { return }
        let types = (pb.types ?? []).map(\.rawValue)
        guard !types.contains(where: privateTypes.contains) else { return }
        let source = NSWorkspace.shared.frontmostApplication?.bundleIdentifier
        if let source, prefs.ignoredApps.contains(source) { return }
        if let clip = Capture.read(pb, source: source, store: store) { onCapture(clip) }
    }
}

@MainActor
enum Capture {
    static func read(_ pb: NSPasteboard, source: String?, store: Store) -> Clip? {
        if let urls = pb.readObjects(forClasses: [NSURL.self], options: [.urlReadingFileURLsOnly: true]) as? [URL],
           !urls.isEmpty {
            let paths = urls.map(\.path)
            return Clip(kind: .files, paths: paths, sourceBundleID: source, hash: Hash.of(paths.joined(separator: "\n")))
        }
        let string = pb.string(forType: .string)
        let imageData = pb.data(forType: .png) ?? pb.data(forType: .tiff)
        if let imageData, string == nil || isSingleURL(string!) {
            return image(imageData, source: source, store: store)
        }
        guard let string, !string.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else { return nil }
        return text(String(string.prefix(200_000)), source: source)
    }

    static func text(_ s: String, source: String?) -> Clip {
        let t = s.trimmingCharacters(in: .whitespacesAndNewlines)
        let kind: ClipKind = ColorParse.color(t) != nil ? .color : (isSingleURL(t) ? .link : .text)
        return Clip(kind: kind, text: kind == .text ? s : t, sourceBundleID: source, hash: Hash.of(kind.rawValue + t))
    }

    static func image(_ data: Data, source: String?, store: Store) -> Clip? {
        let hash = Hash.of(data)
        if store.contains(hash: hash) {
            return Clip(kind: .image, sourceBundleID: source, hash: hash)
        }
        guard let rep = NSBitmapImageRep(data: data) else { return nil }
        let png = data.starts(with: [0x89, 0x50, 0x4E, 0x47]) ? data : rep.representation(using: .png, properties: [:])
        guard let png else { return nil }
        let blob = UUID().uuidString
        try? png.write(to: store.blobURL(blob))
        let size = CGSize(width: rep.pixelsWide, height: rep.pixelsHigh)
        if let thumb = thumbnail(rep, max: 520) { try? thumb.write(to: store.thumbURL(blob)) }
        return Clip(kind: .image, blob: blob, imageSize: size, sourceBundleID: source, hash: hash)
    }

    static func thumbnail(_ rep: NSBitmapImageRep, max side: CGFloat) -> Data? {
        let w = CGFloat(rep.pixelsWide), h = CGFloat(rep.pixelsHigh)
        guard w > 0, h > 0 else { return nil }
        let scale = min(1, side / max(w, h))
        let tw = Int(w * scale), th = Int(h * scale)
        guard let out = NSBitmapImageRep(bitmapDataPlanes: nil, pixelsWide: tw, pixelsHigh: th, bitsPerSample: 8,
                                         samplesPerPixel: 4, hasAlpha: true, isPlanar: false,
                                         colorSpaceName: .deviceRGB, bytesPerRow: 0, bitsPerPixel: 0) else { return nil }
        NSGraphicsContext.saveGraphicsState()
        NSGraphicsContext.current = NSGraphicsContext(bitmapImageRep: out)
        NSColor.white.setFill()
        NSRect(x: 0, y: 0, width: tw, height: th).fill()
        rep.draw(in: NSRect(x: 0, y: 0, width: tw, height: th), from: .zero, operation: .sourceOver, fraction: 1,
                 respectFlipped: false, hints: [.interpolation: NSImageInterpolation.high.rawValue])
        NSGraphicsContext.restoreGraphicsState()
        return out.representation(using: .jpeg, properties: [.compressionFactor: 0.82])
    }

    static func isSingleURL(_ s: String) -> Bool {
        let t = s.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !t.contains(where: \.isWhitespace), let u = URL(string: t), let scheme = u.scheme?.lowercased() else { return false }
        return ["http", "https", "mailto", "ftp", "ssh"].contains(scheme) && (u.host != nil || scheme == "mailto")
    }
}

enum ColorParse {
    static func color(_ s: String) -> NSColor? {
        let t = s.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        if t.hasPrefix("#") {
            let hex = String(t.dropFirst())
            guard [3, 6, 8].contains(hex.count), let v = UInt64(hex, radix: 16) else { return nil }
            switch hex.count {
            case 3:
                let r = (v >> 8) & 0xF, g = (v >> 4) & 0xF, b = v & 0xF
                return NSColor(srgbRed: CGFloat(r * 17) / 255, green: CGFloat(g * 17) / 255, blue: CGFloat(b * 17) / 255, alpha: 1)
            case 6:
                return NSColor(srgbRed: CGFloat((v >> 16) & 0xFF) / 255, green: CGFloat((v >> 8) & 0xFF) / 255,
                               blue: CGFloat(v & 0xFF) / 255, alpha: 1)
            default:
                return NSColor(srgbRed: CGFloat((v >> 24) & 0xFF) / 255, green: CGFloat((v >> 16) & 0xFF) / 255,
                               blue: CGFloat((v >> 8) & 0xFF) / 255, alpha: CGFloat(v & 0xFF) / 255)
            }
        }
        for prefix in ["rgba(", "rgb("] where t.hasPrefix(prefix) && t.hasSuffix(")") {
            let parts = t.dropFirst(prefix.count).dropLast().split(whereSeparator: { $0 == "," || $0 == " " || $0 == "/" })
                .compactMap { Double($0.replacingOccurrences(of: "%", with: "")) }
            guard parts.count >= 3, parts[0...2].allSatisfy({ $0 >= 0 && $0 <= 255 }) else { return nil }
            let a = parts.count > 3 ? (parts[3] > 1 ? parts[3] / 100 : parts[3]) : 1
            return NSColor(srgbRed: parts[0] / 255, green: parts[1] / 255, blue: parts[2] / 255, alpha: a)
        }
        return nil
    }
}

@MainActor
enum Paster {
    static weak var watcher: Watcher?

    static func write(_ clip: Clip, store: Store) {
        let pb = NSPasteboard.general
        pb.clearContents()
        switch clip.kind {
        case .text, .color:
            pb.setString(clip.text ?? "", forType: .string)
        case .link:
            let s = clip.text ?? ""
            pb.declareTypes([.string, .URL], owner: nil)
            pb.setString(s, forType: .string)
            pb.setString(s, forType: .URL)
        case .image:
            if let b = clip.blob, let data = try? Data(contentsOf: store.blobURL(b)) {
                pb.declareTypes([.png, .tiff], owner: nil)
                pb.setData(data, forType: .png)
                if let tiff = NSBitmapImageRep(data: data)?.tiffRepresentation { pb.setData(tiff, forType: .tiff) }
            }
        case .files:
            pb.writeObjects((clip.paths ?? []).map { URL(fileURLWithPath: $0) as NSURL })
        }
        watcher?.skipCurrent()
    }

    static var canAutoPaste: Bool { AXIsProcessTrusted() }

    static func requestAccessibility() {
        let key = kAXTrustedCheckOptionPrompt.takeUnretainedValue() as String
        _ = AXIsProcessTrustedWithOptions([key: true] as CFDictionary)
    }

    /// Presses ⌘V in whatever app is in front.
    static func sendPaste() {
        let src = CGEventSource(stateID: .combinedSessionState)
        let v = CGKeyCode(kVK_ANSI_V)
        let down = CGEvent(keyboardEventSource: src, virtualKey: v, keyDown: true)
        let up = CGEvent(keyboardEventSource: src, virtualKey: v, keyDown: false)
        down?.flags = .maskCommand
        up?.flags = .maskCommand
        down?.post(tap: .cgAnnotatedSessionEventTap)
        up?.post(tap: .cgAnnotatedSessionEventTap)
    }
}

/// A system-wide shortcut through Carbon, which needs no extra permission.
final class HotKey {
    nonisolated(unsafe) static var handler: () -> Void = {}
    private var ref: EventHotKeyRef?
    private static var installed = false

    func register(_ s: Shortcut) {
        if let ref { UnregisterEventHotKey(ref) }
        ref = nil
        if !HotKey.installed {
            HotKey.installed = true
            var spec = EventTypeSpec(eventClass: OSType(kEventClassKeyboard), eventKind: UInt32(kEventHotKeyPressed))
            InstallEventHandler(GetApplicationEventTarget(), { _, _, _ in
                DispatchQueue.main.async { HotKey.handler() }
                return noErr
            }, 1, &spec, nil, nil)
        }
        let id = EventHotKeyID(signature: OSType(0x434C_4E45), id: 1)
        RegisterEventHotKey(s.keyCode, s.modifiers, id, GetApplicationEventTarget(), 0, &ref)
    }
}
